import{_ as i,c as a,o as e,af as l}from"./chunks/framework.CSLzPq2T.js";const c=JSON.parse('{"title":"导入本地存档到面板","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"guide/export_user_cluster.md","filePath":"guide/export_user_cluster.md"}'),t={name:"guide/export_user_cluster.md"};function n(h,s,p,k,o,d){return e(),a("div",null,[...s[0]||(s[0]=[l(`<h1 id="导入本地存档到面板" tabindex="-1">导入本地存档到面板 <a class="header-anchor" href="#导入本地存档到面板" aria-label="Permalink to “导入本地存档到面板”">​</a></h1><p>简介：面板可将本地的《饥荒：联机版》存档导入并进行管理。文档说明默认识别规则与自定义映射方式。</p><h2 id="支持的默认存档格式" tabindex="-1">支持的默认存档格式 <a class="header-anchor" href="#支持的默认存档格式" aria-label="Permalink to “支持的默认存档格式”">​</a></h2><p>面板会自动识别常见的默认存档结构，例如：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>--Cluster_1</span></span>
<span class="line"><span>------Master</span></span>
<span class="line"><span>------Caves</span></span></code></pre></div><p>默认映射：</p><ul><li><code>Master</code> -&gt; 主世界（在面板中通常显示为“森林”）</li><li><code>Caves</code> -&gt; 洞穴世界（在面板中通常显示为“洞穴”）</li></ul><p>导入此结构后，面板会自动识别并创建对应的两个世界项。</p><h2 id="自定义存档-使用-level-json" tabindex="-1">自定义存档（使用 level.json） <a class="header-anchor" href="#自定义存档-使用-level-json" aria-label="Permalink to “自定义存档（使用 level.json）”">​</a></h2><p>如果本地存档结构不是默认格式，需要在存档根目录创建 <code>level.json</code> 以告知面板如何映射世界名称与文件夹。</p><ol><li>将 <code>level.json</code> 放在存档根目录（即 Cluster 文件夹）下。</li><li><code>level.json</code> 的基本结构为：</li></ol><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;levelList&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;显示名称&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;file&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;存档文件夹名&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>字段说明：</p><ul><li><code>name</code>：面板中显示的世界名称（中文或自定义名称）。</li><li><code>file</code>：对应的存档文件夹名（必须与磁盘上文件夹名一致）。</li></ul><p>示例：假设目录结构为</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---Cluster_2</span></span>
<span class="line"><span>------World_A</span></span>
<span class="line"><span>------World_B</span></span>
<span class="line"><span>------World_C</span></span></code></pre></div><p>则可以在 <code>Cluster_2</code> 下创建如下 <code>level.json</code>：</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;levelList&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;森林&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;file&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Master&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;洞穴&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;file&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;World_B&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;地底&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;file&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;World_C&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]}</span></span></code></pre></div><p>放置后最终目录示例：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---Cluster_2</span></span>
<span class="line"><span>------Master</span></span>
<span class="line"><span>------World_B</span></span>
<span class="line"><span>------World_C</span></span>
<span class="line"><span>------level.json</span></span></code></pre></div><h2 id="要求与注意事项" tabindex="-1">要求与注意事项 <a class="header-anchor" href="#要求与注意事项" aria-label="Permalink to “要求与注意事项”">​</a></h2><ul><li>主世界文件夹必须命名为 <code>Master</code>，否则面板无法正确采集主世界数据。</li><li><code>level.json</code> 必须位于存档根目录（Cluster 目录）下。</li><li><code>file</code> 字段应精确对应文件夹名（注意大小写及空格问题）。</li><li>保证 <code>level.json</code> 为合法 JSON；若导入失败，先用 JSON 校验工具检查格式。</li><li>若只存在默认的 <code>Master</code> 与 <code>Caves</code>，无需 <code>level.json</code>，面板会自动识别。</li></ul><h2 id="常见问题排查" tabindex="-1">常见问题排查 <a class="header-anchor" href="#常见问题排查" aria-label="Permalink to “常见问题排查”">​</a></h2><ul><li>导入后未识别世界：确认 <code>Master</code> 是否存在且 <code>level.json</code> 放置在正确位置。</li><li>名称显示错误：检查 <code>level.json</code> 中 <code>name</code> 字段是否正确设置。</li><li>JSON 解析错误：使用在线或本地 JSON 校验器检查 <code>levelList</code> 格式。</li></ul>`,24)])])}const E=i(t,[["render",n]]);export{c as __pageData,E as default};
